/* ================================================================
   paises.js — o contorno de cada país, para o globo
   Do mapa ne_50m_admin_0_countries do Natural Earth (domínio
   público), simplificado. Serve para desenhar costa e fronteiras e
   para saber em que país o dedo ou o mouse está.

   CONTORNOS: cada ponto são dois inteiros de 16 bits, latitude e
   longitude vezes 100. O par (-32768, 0) começa outra parte do mesmo
   país (uma ilha); (-32768, 1) começa o próximo país, na ordem de
   PAISES. 242 países e territórios, 22712 pontos.
   ================================================================ */

